import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

_ptx_module = None
PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry the_entry_name(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K
)
{
    .reg .pred  %p0, %p1, %p2, %p3, %p4;
    .reg .pred  %p5, %p6, %p7, %p8, %p9;
    .reg .u32   %rTid, %rNT, %rBidY, %rM, %rK, %rKiter, %rStride, %rIdx2;
    .reg .u32   %rK4, %rKmod, %rK4iter, %rKbase;
    .reg .u64   %rdA, %rdB, %rdC, %rdRowK, %rdKiter, %rdAelem, %rdAoffB, %rdAaddr;
    .reg .u64   %rdBoffB, %rdBaddr, %rdSbase, %rdTidOff, %rdSaddr, %rdIdx2Off, %rdSaddr2;
    .reg .u64   %rdRow, %rdCoffB, %rdCaddr;
    .reg .u64   %rdA_baseB, %rdArowB, %rdK4iter64, %rdOff16, %rdTmp, %rdTmp2, %rdOffB;
    .reg .f32   %fAcc, %fA, %fB, %fT0, %fT1, %fRes;
    .reg .f32   %fA0, %fA1, %fA2, %fA3, %fB0, %fB1, %fB2, %fB3;
    // Shared memory for block reduction: supports up to 1024 threads (4096 bytes)
    .shared .align 4 .b8 sdata[4096];
    // Load parameters
    ld.param.u64   %rdA, [A_ptr];
    ld.param.u64   %rdB, [B_ptr];
    ld.param.u64   %rdC, [C_ptr];
    ld.param.u32   %rM, [M];
    ld.param.u32   %rK, [K];
    // Thread/block info
    mov.u32        %rTid, %tid.x;
    mov.u32        %rNT,  %ntid.x;
    mov.u32        %rBidY, %ctaid.y;
    // Bounds check for row index
    setp.ge.u32    %p0, %rBidY, %rM;
    @%p0 bra       DONE;
    // Compute base element offset row * K in 64-bit
    mul.wide.u32   %rdRowK, %rBidY, %rK;   // 64-bit: row*K
    // Compute A row base in bytes: A + (row*K)*4
    shl.b64        %rdA_baseB, %rdRowK, 2;
    add.s64        %rdArowB, %rdA, %rdA_baseB;
    // Initialize accumulator
    mov.f32        %fAcc, 0f00000000;
    // Prepare vectorization parameters
    shr.u32        %rK4, %rK, 2;           // K4 = K / 4
    and.b32        %rKmod, %rK, 3;         // Kmod = K % 4
    // Check 16-byte alignment for A row base and B base, and K4 > 0
    and.b64        %rdTmp,  %rdArowB, 0xf;
    setp.eq.b64    %p5, %rdTmp, 0;
    and.b64        %rdTmp2, %rdB, 0xf;
    setp.eq.b64    %p6, %rdTmp2, 0;
    setp.ne.u32    %p7, %rK4, 0;
    and.pred       %p8, %p5, %p6;
    and.pred       %p9, %p8, %p7;
    @!%p9 bra      SCALAR_PATH;
    // Vectorized main loop over K4 with ld.global.v4.f32
    mov.u32        %rK4iter, %rTid;
VEC_LOOP_COND:
    setp.ge.u32    %p1, %rK4iter, %rK4;
    @%p1 bra       VEC_LOOP_END;
    cvt.u64.u32    %rdK4iter64, %rK4iter;
    shl.b64        %rdOff16, %rdK4iter64, 4;       // *16 bytes
    add.s64        %rdAaddr, %rdArowB, %rdOff16;
    add.s64        %rdBaddr, %rdB,      %rdOff16;
    ld.global.v4.f32  {%fA0, %fA1, %fA2, %fA3}, [%rdAaddr];
    ld.global.v4.f32  {%fB0, %fB1, %fB2, %fB3}, [%rdBaddr];
    fma.rn.f32     %fAcc, %fA0, %fB0, %fAcc;
    fma.rn.f32     %fAcc, %fA1, %fB1, %fAcc;
    fma.rn.f32     %fAcc, %fA2, %fB2, %fAcc;
    fma.rn.f32     %fAcc, %fA3, %fB3, %fAcc;
    add.u32        %rK4iter, %rK4iter, %rNT;
    bra            VEC_LOOP_COND;
VEC_LOOP_END:
    // Tail scalar loop for remaining Kmod elements
    setp.eq.u32    %p2, %rKmod, 0;
    @%p2 bra       ACCUM_DONE;
    shl.b32        %rKbase, %rK4, 2;              // base = K4 * 4
    add.u32        %rKiter, %rKbase, %rTid;
TAIL_LOOP_COND:
    setp.ge.u32    %p1, %rKiter, %rK;
    @%p1 bra       ACCUM_DONE;
    cvt.u64.u32    %rdKiter, %rKiter;
    shl.b64        %rdOffB, %rdKiter, 2;          // *4 bytes
    add.s64        %rdAaddr, %rdArowB, %rdOffB;
    add.s64        %rdBaddr, %rdB,      %rdOffB;
    ld.global.f32  %fA, [%rdAaddr];
    ld.global.f32  %fB, [%rdBaddr];
    fma.rn.f32     %fAcc, %fA, %fB, %fAcc;
    add.u32        %rKiter, %rKiter, %rNT;
    bra            TAIL_LOOP_COND;
SCALAR_PATH:
    // Scalar loop over K with stride = blockDim.x
    mov.u32        %rKiter, %rTid;
SCALAR_LOOP_COND:
    setp.ge.u32    %p1, %rKiter, %rK;
    @%p1 bra       ACCUM_DONE;
    cvt.u64.u32    %rdKiter, %rKiter;
    // A address: ArowB + k*4
    shl.b64        %rdAoffB, %rdKiter, 2;     // *4 bytes
    add.s64        %rdAaddr, %rdArowB, %rdAoffB;
    // B address: B + k*4
    shl.b64        %rdBoffB, %rdKiter, 2;     // *4 bytes
    add.s64        %rdBaddr, %rdB, %rdBoffB;
    // Loads
    ld.global.f32  %fA, [%rdAaddr];
    ld.global.f32  %fB, [%rdBaddr];
    // FMA accumulate
    fma.rn.f32     %fAcc, %fA, %fB, %fAcc;
    // k += blockDim.x
    add.u32        %rKiter, %rKiter, %rNT;
    bra            SCALAR_LOOP_COND;
ACCUM_DONE:
    // Shared memory base
    mov.u64        %rdSbase, sdata;
    // Store partial sum to shared memory at sdata[tid]
    mul.wide.u32   %rdTidOff, %rTid, 4;
    add.s64        %rdSaddr, %rdSbase, %rdTidOff;
    st.shared.f32  [%rdSaddr], %fAcc;
    // Sync before reduction
    bar.sync 0;
    // s = blockDim.x >> 1
    shr.u32        %rStride, %rNT, 1;
REDUCE_LOOP_COND:
    setp.eq.u32    %p2, %rStride, 0;
    @%p2 bra       REDUCE_DONE;
    // If (tid < s) then reduce with neighbor
    setp.ge.u32    %p3, %rTid, %rStride;
    @%p3 bra       REDUCE_SKIP;
    // Load self
    ld.shared.f32  %fT0, [%rdSaddr];
    // Neighbor index = tid + s
    add.u32        %rIdx2, %rTid, %rStride;
    mul.wide.u32   %rdIdx2Off, %rIdx2, 4;
    add.s64        %rdSaddr2, %rdSbase, %rdIdx2Off;
    // Load neighbor and add
    ld.shared.f32  %fT1, [%rdSaddr2];
    add.f32        %fT0, %fT0, %fT1;
    // Store back
    st.shared.f32  [%rdSaddr], %fT0;
REDUCE_SKIP:
    // Sync all threads before next step
    bar.sync 0;
    // s >>= 1
    shr.u32        %rStride, %rStride, 1;
    bra            REDUCE_LOOP_COND;
REDUCE_DONE:
    // Thread 0 writes the result to C[row]
    setp.ne.u32    %p4, %rTid, 0;
    @%p4 bra       DONE;
    // Load final sum from sdata[0]
    ld.shared.f32  %fRes, [%rdSbase];
    // C address = C + row*4
    cvt.u64.u32    %rdRow, %rBidY;
    shl.b64        %rdCoffB, %rdRow, 2;
    add.s64        %rdCaddr, %rdC, %rdCoffB;
    st.global.f32  [%rdCaddr], %fRes;
DONE:
    ret;
}
"""
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

